export async function checkOutgoingNewDestinationReadOnly(tools){
  const {evaluate,wait,click,report,capture}=tools;assert.equal(await evaluate("app.vault.readOnly"),true);const savedOwner=await captureOwner(tools),proofs=[];let paneId,failure;
  const documents='app.metadataCache.getDocuments().map(e=>({path:e.document.file.path,text:e.text,version:e.document.version,bom:e.document.hasBom===true})).sort((a,b)=>a.path.localeCompare(b.path))',before=await evaluate(documents),beforeCounters=await evaluate('(()=>{const{api,raw}=app.githubVaults.state().counters;return{api,raw}})()');
  await evaluate(`(()=>{const t=${trace}={reads:[],exists:[],creates:[],originalRead:app.vault.readDocument,originalExists:app.vault.adapter.exists,originalCreate:app.vault.create};t.read=function(path,...args){t.reads.push(path);return t.originalRead.call(this,path,...args)};t.existsWrapper=function(path,...args){t.exists.push(path);return t.originalExists.call(this,path,...args)};t.create=function(path,...args){t.creates.push(path);return t.originalCreate.call(this,path,...args)};app.vault.readDocument=t.read;app.vault.adapter.exists=t.existsWrapper;app.vault.create=t.create;return true})()`);
  try{
    paneId=await evaluate(`(async()=>{const leaf=app.workspace.createLeafBySplit(${owner}.leaf,'vertical');await leaf.setViewState({type:'outgoing-link',state:{file:'Read only.md',followActiveFile:false,unlinkedCollapsed:false},active:true});return leaf.id})()`);
    const selector=`[data-outgoing-pane=${q(paneId)}] [data-outgoing-new-open]`;
    const probe=async label=>{await evaluate('(async()=>{await app.workspace.whenIdle();if(app.metadataCache.pending)await app.metadataCache.pending;await app.core.whenIdle()})()');await wait(`Boolean(document.querySelector(${q(selector)})?.checkVisibility())`,"actual cached new-destination control is visible");assert.equal(await evaluate(`document.querySelector(${q(selector)}).disabled`),true);const counts=await evaluate(`({reads:${trace}.reads.length,exists:${trace}.exists.length,creates:${trace}.creates.length,sessions:app.workspace.sessions.size,leaves:app.workspace.leaves().length})`);const pointer=await disabledPointer(tools,selector);await evaluate(`app.workspace.getLeafById(${q(paneId)}).view.openNewDestination()`);const result=await evaluate(`({reads:${trace}.reads.length,exists:${trace}.exists.length,creates:${trace}.creates.length,sessions:app.workspace.sessions.size,leaves:app.workspace.leaves().length,modal:Boolean(document.querySelector(${q(modal)}))})`);assert.deepEqual(result,{...counts,modal:false});proofs.push({label,pointer,before:counts,after:result,forcedHandler:'supplemental direct stale/readonly refusal'});};
    await probe("cached Source");await evaluate(`(async()=>{${owner}.view.setEditingMode('preview',false);await ${owner}.view.currentMode.whenReady()})()`);await probe("cached Reading");await evaluate(`app.workspace.getLeafById(${q(paneId)}).view.setFile(app.vault.getFileByPath('New destination cached closed.md'))`);await wait(`app.workspace.getLeafById(${q(paneId)}).view.snapshot?.path==='New destination cached closed.md'`);assert.equal(await evaluate("app.workspace.sessions.has('New destination cached closed.md')"),false);await probe("cached closed Source");
    proofs.push({label:'cached legacy sidebar navigation',sidebar:await showRightProvider(tools,'outgoing-link')});await wait("Boolean(document.querySelector('.outgoing-link-pane [data-outgoing-new-open]')?.checkVisibility())");assert.equal(await evaluate("document.querySelector('.outgoing-link-pane [data-outgoing-new-open]').disabled"),true);const beforeLegacy=await evaluate(`({reads:${trace}.reads.length,exists:${trace}.exists.length,creates:${trace}.creates.length,sessions:app.workspace.sessions.size,leaves:app.workspace.leaves().length})`);const legacyPointer=await disabledPointer(tools,'.outgoing-link-pane [data-outgoing-new-open]');await evaluate("(()=>{const b=document.querySelector('.outgoing-link-pane [data-outgoing-new-open]');b.disabled=false;b.click();b.disabled=true;return true})()");assert.deepEqual(await evaluate(`({reads:${trace}.reads.length,exists:${trace}.exists.length,creates:${trace}.creates.length,sessions:app.workspace.sessions.size,leaves:app.workspace.leaves().length})`),beforeLegacy);assert.equal(await evaluate(`Boolean(document.querySelector(${q(modal)}))`),false);proofs.push({label:"cached legacy forced disabled handler",pointer:legacyPointer,before:beforeLegacy,forcedHandler:'supplemental synthetic disabled-handler refusal'});
    assert.deepEqual(await evaluate(documents),before);assert.deepEqual(await evaluate('(()=>{const{api,raw}=app.githubVaults.state().counters;return{api,raw}})()'),beforeCounters);await wait('document.querySelectorAll(".notice").length===0',"readonly capture is free of temporary notices");await capture?.("outgoing-new-readonly");
    report.outgoingNewDestinationReadOnly={genuineCachedMount:true,sourceAndReadingDisabled:true,closedDisabled:true,legacyDisabled:true,trustedDisabledPointer:true,forcedHandlerRefused:true,noAuthoringReads:true,noExistenceChecks:true,noCreates:true,noSourceAllocation:true,noModal:true,exactMergedCachedSource:true,exactCachedDocuments:true,zeroApiRaw:true,originalOwnerRetained:true};report.outgoingNewDestinationReadOnlyProof={savedOwner,proofs,documents:before,readLedger:await evaluate(`({reads:${trace}.reads,exists:${trace}.exists,creates:${trace}.creates})`)};
    pass(tools,"Genuine cached read-only Outgoing controls and forced handlers refuse Source, Reading, closed and legacy new destinations before reads, existence probes, file creation, Source allocation or a review dialog.");
  }catch(error){failure=error;report.outgoingNewDestinationReadOnlyFailure={error:String(error?.stack??error),proofs};throw error;}
  finally{try{await evaluate(`(async()=>{const o=${owner};o.view.setEditingMode(o.mode,false);if(o.view.getMode()==='preview')await o.view.currentMode.whenReady();if(${q(paneId)}){const l=app.workspace.getLeafById(${q(paneId)});if(l)await app.workspace.closeLeaf(l)}return true})()`);report.outgoingNewDestinationReadOnlyOwner=await restoreOwner(tools);assert.deepEqual(await evaluate(documents),before);}catch(error){if(!failure)throw error;report.outgoingNewDestinationReadOnlyCleanupError=String(error?.stack??error);}finally{await evaluate(`(()=>{const t=${trace};if(t){if(app.vault.readDocument===t.read)app.vault.readDocument=t.originalRead;if(app.vault.adapter.exists===t.existsWrapper)app.vault.adapter.exists=t.originalExists;if(app.vault.create===t.create)app.vault.create=t.originalCreate;delete ${trace}}return true})()`);}}
}
